// ==============================================================================
// Smart Parking AI — Power Query M Formula
// Loads real parking occupancy telemetry from the CSV generated by FastAPI
// ==============================================================================

let
    // Option A: Load from local file path
    Source = Csv.Document(File.Contents("C:\Users\kesha\Desktop\Smart-Parking-AI\outputs\powerbi\parking_occupancy.csv"),[Delimiter=",", Columns=10, Encoding=65001, QuoteStyle=QuoteStyle.None]),
    
    // Promote first row to headers
    #"Promoted Headers" = Table.PromoteHeaders(Source, [PromoteAllScalars=true]),
    
    // Explicitly set column types:
    // Slot_ID and Status are Categorical (Text)
    // Confidence, Occupancy_Percentage are Decimal Numbers
    // Total_Slots, Occupied_Slots, Vacant_Slots are Integers
    // Date is Date, Time is Time
    #"Changed Type" = Table.TransformColumnTypes(#"Promoted Headers",{
        {"Date", type date}, 
        {"Time", type time}, 
        {"Parking_Lot", type text}, 
        {"Slot_ID", type text}, 
        {"Status", type text}, 
        {"Confidence", type number}, 
        {"Total_Slots", Int64.Type}, 
        {"Occupied_Slots", Int64.Type}, 
        {"Vacant_Slots", Int64.Type}, 
        {"Occupancy_Percentage", type number}
    })
in
    #"Changed Type"
